// Improved Express.js application with configuration and basic security

const express = require('express');
const { config } = require('./config');
require('dotenv').config();

const app = express();

// Basic security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// Simple CORS for development
if (config.server.environment === 'development') {
  app.use((req, res, next) => {
    res.header('Access-Control-Allow-Origin', 'http://localhost:3000');
    res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
    next();
  });
}

// Basic rate limiting
let requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();
  const windowMs = 15 * 60 * 1000; // 15 minutes
  const maxRequests = 100;

  if (!requestCounts.has(ip)) {
    requestCounts.set(ip, { count: 1, startTime: now });
  } else {
    const ipData = requestCounts.get(ip);
    if (now - ipData.startTime > windowMs) {
      // Reset counter if window has passed
      ipData.count = 1;
      ipData.startTime = now;
    } else if (ipData.count >= maxRequests) {
      return res.status(429).json({ 
        message: 'Too many requests, please try again later.' 
      });
    } else {
      ipData.count++;
    }
  }

  next();
});

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.server.environment
  });
});

// Users endpoint using configured sample data
app.get('/users', (req, res) => {
  res.json(config.app.sampleUsers);
});

// Simple input validation for query parameters
app.get('/users/:id', (req, res) => {
  const userId = parseInt(req.params.id);

  if (isNaN(userId) || userId <= 0) {
    return res.status(400).json({ 
      error: 'Invalid user ID. Must be a positive integer.' 
    });
  }

  const user = config.app.sampleUsers.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ 
      error: 'User not found' 
    });
  }

  res.json(user);
});

// Error handling
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({ 
    error: 'Internal server error',
    ...(config.server.environment === 'development' && { details: err.message })
  });
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

app.listen(config.server.port, () => {
  console.log(`Server running on port ${config.server.port}`);
  console.log(`Environment: ${config.server.environment}`);
});

module.exports = app;

