# Security Improvements Required

## Critical Issues

### 1. Environment File Security
- Remove `.env.test` from source control
- Add to `.gitignore`:
```
.env*
!.env.example
```
- Use environment variables or secure secret management

### 2. Dependency Management
Create `package.json`:
```json
{
  "name": "secure-app",
  "version": "1.0.0",
  "description": "Secure Express.js application",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "jest"
  },
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.1.0",
    "express-rate-limit": "^7.1.5",
    "cors": "^2.8.5",
    "express-validator": "^7.0.1"
  },
  "devDependencies": {
    "nodemon": "^3.0.2",
    "jest": "^29.7.0"
  }
}
```

## Application Security Hardening

### Enhanced app.js with security:

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors({
  origin: process.env.NODE_ENV === 'production' ? 'https://yourdomain.com' : '*',
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Health endpoint with reduced information
app.get('/health', (req, res) => {
  res.json({ status: 'ok' }); // Removed timestamp to prevent timing attacks
});

// Users endpoint with validation
app.get('/users', [
  // Add query parameter validation if needed
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Something went wrong!' });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

## Additional Security Measures

1. **Environment Configuration**:
   - Create `.env.example` with placeholder values
   - Use `dotenv` package for development
   - Never commit actual credentials

2. **Dependency Security**:
   - Run `npm audit` regularly
   - Use `npm audit fix` to address vulnerabilities
   - Consider using Snyk or similar tools

3. **API Security**:
   - Implement proper authentication/authorization
   - Validate all inputs
   - Sanitize outputs
   - Use HTTPS in production

4. **Monitoring**:
   - Implement logging (without sensitive data)
   - Set up intrusion detection
   - Monitor for abnormal patterns

// Secure Express.js application with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// 1. Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"]
    }
  }
}));

// 2. CORS configuration
app.use(cors({
  origin: process.env.NODE_ENV === 'production' ? 
    ['https://yourdomain.com'] : ['http://localhost:3000', 'http://localhost:8080'],
  methods: ['GET', 'POST'],
  credentials: true
}));

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Body parsing with size limits to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Request logging middleware (without sensitive data)
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Health endpoint - minimal information disclosure
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok',
    // Removed timestamp to prevent timing attacks
    // Only include necessary information
  });
});

// Users endpoint with basic security
app.get('/users', (req, res) => {
  // Simple input validation example
  const { page, limit } = req.query;

  if (page && isNaN(parseInt(page))) {
    return res.status(400).json({ error: 'Invalid page parameter' });
  }

  if (limit && isNaN(parseInt(limit))) {
    return res.status(400).json({ error: 'Invalid limit parameter' });
  }

  // Sample response with minimal sensitive data
  res.json([
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com', // Consider masking emails in production
      role: 'user' 
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      role: 'user' 
    },
  ]);
});

// 6. Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.message);
  // Don't expose stack traces in production
  res.status(500).json({ 
    error: process.env.NODE_ENV === 'production' ? 
      'Internal server error' : err.message 
  });
});

// 7. 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

