const express = require('express');
require('dotenv').config(); // Load environment variables

const app = express();

// Configuration from environment variables
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const API_PREFIX = process.env.API_PREFIX || '';

// Optional: Mock user data (in production, this would come from a database)
const MOCK_USERS = process.env.MOCK_USERS ? JSON.parse(process.env.MOCK_USERS) : [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Health check endpoint
app.get(`${API_PREFIX}/health`, (req, res) => {
  res.json({ 
    status: 'ok', 
    environment: NODE_ENV,
    // Removed timestamp to prevent information disclosure
  });
});

// Users endpoint - in production, this would connect to a real database
app.get(`${API_PREFIX}/users`, (req, res) => {
  // Basic input validation
  const { page = 1, limit = 10 } = req.query;

  if (isNaN(parseInt(page)) || isNaN(parseInt(limit))) {
    return res.status(400).json({ 
      error: 'Invalid pagination parameters',
      message: 'Page and limit must be numbers'
    });
  }

  // Simulate database response with mock data
  res.json({
    users: MOCK_USERS,
    pagination: {
      page: parseInt(page),
      limit: parseInt(limit),
      total: MOCK_USERS.length
    }
  });
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${NODE_ENV}`);
  if (API_PREFIX) {
    console.log(`API Prefix: ${API_PREFIX}`);
  }
});

module.exports = app;

